// Actual persistent broker journal, two rotations and restored external-flat token.
#include "host_compat.hpp"
#include "HG6Broker.mqh"
int main(){
 mock_tester=true;mock_clock=1;MqlTick t;t.time=1;t.time_msc=1000;t.bid=2000.;t.ask=2000.01;t.flags=6;mock_ticks={t};mock_visible=1;std::vector<uchar> id;assert(HG6TextDigest("journal-rotation",id));auto broker=std::make_unique<HG6Broker>();assert(broker->Init(_Symbol,17,"rotation",id,true));HG6Exposure x;long seq=0;int rotations=0;double net=0;long dropped=0;
 for(int k=0;k<206;k++){
  assert(HG6ExposureRead(_Symbol,17,x)&&!x.ticket);assert(broker->Submit(1,k,1,1,t,x,10));assert(HG6ExposureRead(_Symbol,17,x)&&broker->Reconcile(x));long mark=broker->JournalLast();assert(broker->Reconcile(x)&&broker->JournalLast()==mark);seq++;assert(broker->ReleaseApplied(seq,seq+1)); // generation monotonic; verified in joint-process tests
  assert(broker->Submit(2,k,-1,1,t,x,10));assert(HG6ExposureRead(_Symbol,17,x)&&!x.ticket&&broker->Reconcile(x));mark=broker->JournalLast();assert(broker->Reconcile(x)&&broker->JournalLast()==mark);seq++;assert(broker->ReleaseApplied(seq,seq+1));
  if(broker->JournalCurrent()==0){rotations++;assert(broker->JournalPrevious()>=HG6_JOURNAL_ROTATE);assert(broker->JournalDropped()>=dropped);dropped=broker->JournalDropped();auto restored=std::make_unique<HG6Broker>();assert(restored->Init(_Symbol,17,"rotation",id,true)&&restored->Ready()&&restored->CheckLink(seq,seq+1)&&!restored->CheckLink(seq,seq));assert(restored->JournalLast()==broker->JournalLast()&&restored->JournalDropped()==dropped);broker=std::move(restored);}
 }
 assert(rotations==2&&broker->JournalLast()==2060&&broker->JournalDropped()==1030&&broker->ClosedPositions()==206&&send_count==412);int deals=0;HG6JournalRow r;assert(!broker->JournalRead(dropped,r));for(long i=dropped+1;i<=broker->JournalLast();i++){assert(broker->JournalRead(i,r)&&r.number==i);if(r.type==HG6_J_DEAL){auto d=find_d((ulong)r.deal);assert(d&&r.order==(long)d->order&&r.position==(long)d->pos&&r.ms==d->ms&&r.volume==d->volume&&r.price==d->price&&r.profit==d->profit&&r.commission==d->commission&&r.swap==d->swap&&r.fee==d->fee);deals++;}}assert(deals==206);for(auto&d:md)net+=d.profit+d.commission+d.swap+d.fee;assert(std::abs(net-broker->ActualNet())<1e-8);
 // External liquidation: persist the authoritative facts without a submitted close,
 // then restore before checkpoint application. No admissions until external release.
 assert(HG6ExposureRead(_Symbol,17,x)&&broker->Submit(1,999,1,1,t,x,10));assert(HG6ExposureRead(_Symbol,17,x)&&broker->Reconcile(x));seq++;assert(broker->ReleaseApplied(seq,seq+1));long pos=x.identifier;md.push_back({++mock_next,++mock_next,0,(ulong)pos,1001,DEAL_ENTRY_OUT,DEAL_TYPE_SELL,.01,t.bid,-.01,-.01,0,0,_Symbol});mock_pt=0;mock_volume=0;assert(broker->ExternalFlat(pos)&&!broker->Ready()&&broker->ExternalPending()==pos);long last=broker->JournalLast();auto restored=std::make_unique<HG6Broker>();assert(restored->Init(_Symbol,17,"rotation",id,true)&&restored->ExternalPending()==pos&&!restored->Ready());assert(restored->ExternalFlat(pos)&&restored->JournalLast()==last);assert(!restored->ReleaseExternal(pos+1,seq,seq+2)&&!restored->ReleaseExternal(pos,seq,seq+1));assert(restored->ReleaseExternal(pos,seq,seq+2)&&restored->Ready()&&!restored->CheckLink(seq,seq+1)&&restored->CheckLink(seq,seq+2));assert(restored->ClosedPositions()==207&&send_count==413);assert(restored->JournalRead(restored->JournalLast(),r)&&r.type==HG6_J_EXTERNAL_RELEASE&&r.position==pos&&r.generation==seq+2);
 std::cout<<"PASS actual broker journal: 206 lifecycles, 2 rotations, 206 retained deal records exact, external-flat pending restore and checkpoint watermark; no duplicate sends\n";
}
